class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) return null;

        Map<Node, Node> map = new HashMap<>();
        Queue<Node> queue = new ArrayDeque<>();
        map.put(node, new Node(node.val));
        queue.offer(node);

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            for (Node neighbor : current.neighbors) {
                if (!map.containsKey(neighbor)) {
                    map.put(neighbor, new Node(neighbor.val));
                    queue.offer(neighbor);
                }
                map.get(current).neighbors.add(map.get(neighbor));
            }
        }

        return map.get(node);
    }
}

import java.util.*;

class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) return null;

        Map<Node, Node> clones = new HashMap<>();
        List<Node> originals = new ArrayList<>();
        Deque<Node> stack = new ArrayDeque<>();
        clones.put(node, new Node(node.val));
        stack.push(node);

        while (!stack.isEmpty()) {
            Node current = stack.pop();
            originals.add(current);
            for (Node neighbor : current.neighbors) {
                if (!clones.containsKey(neighbor)) {
                    clones.put(neighbor, new Node(neighbor.val));
                    stack.push(neighbor);
                }
            }
        }

        for (Node original : originals) {
            Node copy = clones.get(original);
            for (Node neighbor : original.neighbors) {
                copy.neighbors.add(clones.get(neighbor));
            }
        }

        return clones.get(node);
    }
}

import java.util.*;

class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) return null;

        Node[] clones = new Node[101];
        boolean[] seen = new boolean[101];
        Deque<Node> queue = new ArrayDeque<>();

        clones[node.val] = new Node(node.val);
        seen[node.val] = true;
        queue.offer(node);

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            Node copy = clones[current.val];
            for (Node neighbor : current.neighbors) {
                if (clones[neighbor.val] == null) {
                    clones[neighbor.val] = new Node(neighbor.val);
                }
                copy.neighbors.add(clones[neighbor.val]);
                if (!seen[neighbor.val]) {
                    seen[neighbor.val] = true;
                    queue.offer(neighbor);
                }
            }
        }

        return clones[node.val];
    }
}
